package com.codecircle.auth;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} record AuthRequest(@NotBlank @Size(min=3,max=32) String username,@NotBlank @Size(min=8,max=128) String password){} record AuthResponse(String token,String username){}
@PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody AuthRequest r){if(!r.username().matches("[A-Za-z0-9_.-]+"))return ResponseEntity.badRequest().body(Map.of("message","Invalid username"));if(users.existsByUsername(r.username()))return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("message","Username already exists"));AppUser u=users.save(new AppUser(r.username(),encoder.encode(r.password())));return ResponseEntity.ok(new AuthResponse(jwt.create(u.username),u.username));}
@PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody AuthRequest r){return users.findByUsername(r.username()).filter(u->encoder.matches(r.password(),u.passwordHash)).<ResponseEntity<?>>map(u->ResponseEntity.ok(new AuthResponse(jwt.create(u.username),u.username))).orElseGet(()->ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("message","Invalid credentials")));}}
